        left, right = _clean(left), _clean(right)
        tname = aliases.get(left.lower(), left)
        for t in tables:
            if t.lower() == tname.lower():
                for c in tables[t]["cols"]:
                    if c.lower() == right.lower():
                        return (t, c)
        return None
    hits = []
    for alias, tname in aliases.items():
        for t in tables:
            if t.lower() == tname.lower():
                for c in tables[t]["cols"]:
                    if c.lower() == ref.lower():
                        hits.append((t, c))
    uniq = list(dict.fromkeys(hits))
    return uniq[0] if len(uniq) == 1 else None


def _aliases(sql, tables):
    aliases = {}
    for m in ALIAS_RE.finditer(sql or ""):
        tname, alias = m.group(1), _clean(m.group(2) or "")
        real = None
        for t in tables:
            if t.lower() == tname.lower():
                real = t
                break
        if real is None:
            continue
        aliases[real.lower()] = real
        if alias and alias.lower() not in NOT_KEYWORDS:
            aliases[alias.lower()] = real
    return aliases


def _q(val):
    return "'" + str(val).replace("'", "''") + "'"


def _run(env, sql, max_rows=8):
    try:
        res = env.execute(sql, max_rows=max_rows)
    except Exception as exc:  # defensive: never let diagnostics kill the task
        return {"ok": False, "error": str(exc), "rows": [], "columns": [], "n_rows": 0}
    if not isinstance(res, dict):
        return {"ok": False, "error": "no result", "rows": [], "columns": [], "n_rows": 0}
    return res


def _fmt_rows(res, limit=6):
    rows = res.get("rows") or []
    out = []
    for r in rows[:limit]:
        out.append(str(list(r) if isinstance(r, (list, tuple)) else r))
    return "; ".join(out)


def diagnose(sql, tables, env, cfg):
    """Concrete, execution-backed notes about why a draft may be wrong."""
    notes = []
    aliases = _aliases(sql, tables)
    probes = 0
    max_probes = int(cfg.get("max_probe_queries", 8))

    def probe(q):
        nonlocal probes
        if probes >= max_probes:
            return None
        probes += 1
        return _run(env, q, max_rows=6)

    # 1. equality literals that do not exist in their column
    seen = set()
    for m in EQ_LIT.finditer(sql or ""):
        key = (m.group(1).lower(), m.group(2))
        if key in seen:
            continue
        seen.add(key)
        tc = _resolve(m.group(1), aliases, tables)
        if not tc:
            continue
        t, c = tc
        val = m.group(2)
        exact = probe("SELECT COUNT(*) FROM \"%s\" WHERE \"%s\" = %s" % (t, c, _q(val)))
        if not exact.get("ok") or not exact.get("rows"):
            continue
        try:
            n_exact = int(exact["rows"][0][0])
        except Exception:
            continue
        if n_exact > 0:
            continue
        tokens = [w for w in re.split(r"[^A-Za-z0-9]+", val) if len(w) >= 3]
        cond = " OR ".join("\"%s\" LIKE '%%%s%%'" % (c, w) for w in tokens[:3])
        if not cond:
            cond = "\"%s\" LIKE '%%%s%%'" % (c, val.strip())
        loose = probe("SELECT DISTINCT \"%s\" FROM \"%s\" WHERE %s LIMIT 6" % (c, t, cond))
        sample = probe("SELECT DISTINCT \"%s\" FROM \"%s\" LIMIT 8" % (c, t))
        note = "Literal %s does NOT occur in %s.%s (0 exact matches)." % (_q(val), t, c)
        if loose and loose.get("ok") and loose.get("rows"):
            note += " Values actually stored there that contain part of it: " + _fmt_rows(loose) + "."
        elif sample and sample.get("ok") and sample.get("rows"):
            note += " Sample stored values: " + _fmt_rows(sample) + "."
        note += " Use the exact stored spelling/case, or match the right column."
        notes.append(note)

    # 2. LIKE patterns that match nothing but would match without wildcards/spacing
    for m in LIKE_LIT.finditer(sql or ""):
        tc = _resolve(m.group(1), aliases, tables)
        if not tc:
            continue
        t, c = tc
        pat = m.group(2)
        core = pat.replace("%", "").replace("_", " ").strip()
        if not core:
            continue
        orig = probe("SELECT COUNT(*) FROM \"%s\" WHERE \"%s\" LIKE %s" % (t, c, _q(pat)))
        if not orig.get("ok") or not orig.get("rows"):
            continue
        try:
            if int(orig["rows"][0][0]) > 0:
                continue
        except Exception:
            continue
        relaxed = probe(
            "SELECT COUNT(*) FROM \"%s\" WHERE \"%s\" LIKE %s" % (t, c, _q("%" + core + "%"))
        )
        n_relaxed = 0
        if relaxed.get("ok") and relaxed.get("rows"):
            try:
                n_relaxed = int(relaxed["rows"][0][0])
            except Exception:
                n_relaxed = 0
        if n_relaxed > 0:
            ex = probe(
                "SELECT \"%s\" FROM \"%s\" WHERE \"%s\" LIKE %s LIMIT 3"
                % (c, t, c, _q("%" + core + "%"))
            )
            notes.append(
                "LIKE pattern %s on %s.%s matches 0 rows, but '%%%s%%' matches %d rows (examples: %s). "
                "Stray spaces / wrong wildcard placement in the pattern are the likely cause."
                % (_q(pat), t, c, core, n_relaxed, _fmt_rows(ex or {}) or "n/a")
            )
        else:
            sample = probe("SELECT DISTINCT \"%s\" FROM \"%s\" LIMIT 8" % (c, t))
            notes.append(
                "LIKE pattern %s on %s.%s matches 0 rows and even '%%%s%%' matches none. "
                "Sample stored values: %s. Re-check the column and the searched text."
                % (_q(pat), t, c, core, _fmt_rows(sample or {}) or "n/a")
            )

    # 3. IN-list literals absent from their column
    for m in IN_LIST.finditer(sql or ""):
        head = (sql or "")[: m.start()]
        cm = None
        for cm in QUAL_COL.finditer(head):
            pass
        tail = re.search(r"(\"?" + IDENT + r"\"?(?:\s*\.\s*\"?" + IDENT + r"\"?)?)\s*(?:NOT\s+)?$", head, re.I)
        if not tail:
            continue
        tc = _resolve(tail.group(1), aliases, tables)
        if not tc:
            continue
        t, c = tc
        vals = STR_LIT.findall(m.group(1))
        bad = []
        for v in vals[:4]:
            r = probe("SELECT COUNT(*) FROM \"%s\" WHERE \"%s\" = %s" % (t, c, _q(v)))
            if r.get("ok") and r.get("rows"):
                try:
                    if int(r["rows"][0][0]) == 0:
                        bad.append(v)
                except Exception:
                    pass
        if bad:
            sample = probe("SELECT DISTINCT \"%s\" FROM \"%s\" LIMIT 10" % (c, t))
            notes.append(
                "These IN-list values do not exist in %s.%s: %s. Sample stored values: %s."
                % (t, c, ", ".join(_q(v) for v in bad), _fmt_rows(sample or {}) or "n/a")
            )

    # 4. unknown columns / tables referenced with a qualifier
    used_tables = []
    for m in FROM_JOIN.finditer(sql or ""):
        for t in tables:
            if t.lower() == m.group(1).lower() and t not in used_tables:
                used_tables.append(t)
    known = set()
    for t in used_tables:
        known.update(c.lower() for c in tables[t]["cols"])
    all_cols = set()
    for t in tables:
        all_cols.update(c.lower() for c in tables[t]["cols"])
    unknown = []
    for m in QUAL_COL.finditer(sql or ""):
        col = _clean(m.group(2)).lower()
        if col in known or col in all_cols or col in NOT_KEYWORDS:
            continue
        if col not in unknown:
            unknown.append(col)
    if unknown:
        listing = "; ".join("%s(%s)" % (t, ", ".join(tables[t]["cols"])) for t in used_tables)
        notes.append(
            "Columns %s are not declared in the referenced tables. Actual columns: %s."
            % (", ".join(unknown), listing)
        )

    # 5. declared foreign keys of the touched tables (join-path evidence)
    fk_lines = []
    for t in used_tables:
        for a, rt, b in tables[t]["fks"]:
            fk_lines.append("%s.%s -> %s.%s" % (t, a, rt, b))
    if fk_lines:
        notes.append("Declared foreign keys of the tables you used: " + "; ".join(fk_lines) + ".")
    return notes


def _result_note(res):
    if not res.get("ok"):
        return "Execution ERROR: %s" % (res.get("error") or "unknown error")
    n = res.get("n_rows", len(res.get("rows") or []))
    cols = res.get("columns") or []
    if not res.get("rows"):
        return (
            "It executed but returned 0 rows (columns: %s). The gold answer is very likely non-empty, "
            "so some predicate, literal or join is wrong." % ", ".join(map(str, cols))
        )
    return "It returned %s row(s); columns %s; first rows: %s." % (
        n,
        ", ".join(map(str, cols)),
        _fmt_rows(res, limit=5),
    )


def solve(task, env):
    cfg = env.config or {}
    db_id = task["db_id"]
    schema = env.schema(db_id)
    tables = parse_schema(schema)

    user = "Database: %s\n\nSchema:\n%s\n" % (db_id, schema)
    desc = ""
    try:
        desc = env.descriptions(db_id) or ""
    except Exception:
        desc = ""
    if desc.strip() and cfg.get("use_descriptions", True):
        user += "\nColumn descriptions:\n%s\n" % desc.strip()[:2500]
    user += "\nQuestion: %s" % task["question"]
    if task.get("hint"):
        user += "\nHint: %s" % task["hint"]
    user += (
        "\n\nWrite ONE SQLite query that answers the question exactly. "
        "Return it in a single ```sql block."
    )

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=int(cfg.get("max_tokens", 1100)))
    sql = extract_sql(reply)
    if not sql:
        return {"sql": "SELECT 1"}

    if not cfg.get("verify", True):
        return {"sql": sql}

    res = _run(env, sql, max_rows=int(cfg.get("preview_rows", 8)))
    empty = bool(res.get("ok")) and not res.get("rows")
    broken = not res.get("ok")
    if not (empty or broken):
        return {"sql": sql}

    notes = [_result_note(res)]
    if cfg.get("diagnose", True):
        try:
            notes.extend(diagnose(sql, tables, env, cfg))
        except Exception:
            pass
    if empty:
        notes.append(
            "Debug systematically: test each WHERE predicate and each join separately against the real "
            "data, find which one kills all rows, and fix that one. Do not invent tables or columns."
        )
    feedback = (
        "Your query was executed on the real database.\n\nQuery:\n%s\n\n%s\n\n%s\n\n"
        "Return a corrected query that answers the ORIGINAL question (same requested columns, "
        "same intent). Keep any ORDER BY / LIMIT the question implies. "
        "Reply with a single ```sql block containing only the final query."
        % (sql, notes[0], "\n".join("- " + n for n in notes[1:]))
    )
    messages = messages + [
        {"role": "assistant", "content": "```sql\n%s\n```" % sql},
        {"role": "user", "content": feedback},
    ]
    try:
        reply2 = env.chat(messages, max_tokens=int(cfg.get("repair_max_tokens", 1100)))
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    res2 = _run(env, sql2, max_rows=int(cfg.get("preview_rows", 8)))
    if res2.get("ok") and (res2.get("rows") or not empty):
        return {"sql": sql2}
    if res2.get("ok") and not res.get("ok"):
        return {"sql": sql2}
    return {"sql": sql2 if res2.get("ok") else sql}
